$ErrorActionPreference="Stop";$workspace=(Resolve-Path(Join-Path $PSScriptRoot "..\..\..")).Path;$runtime=Join-Path $workspace "runtime\fx-forward-points";$line=Get-Content(Join-Path $workspace ".env")|Where-Object{$_ -match '^DATABASE_URL='}|Select-Object -First 1;$u=[System.UriBuilder]::new($line.Substring(13).Trim().Trim('"').Trim("'"));if($u.Port-ne 6543){throw"TRANSACTION_POOLING_6543_REQUIRED"};$parts=@($u.Query.TrimStart('?').Split('&',[System.StringSplitOptions]::RemoveEmptyEntries)|Where-Object{$_ -notmatch '^(pgbouncer|connection_limit)='});$u.Query=(@($parts)+'pgbouncer=true'+'connection_limit=1')-join'&';$env:DATABASE_URL=$u.Uri.AbsoluteUri;$node=(Get-Command node.exe).Source;$p=Start-Process -FilePath $node -ArgumentList @("--experimental-strip-types","--env-file=.env","scripts/data/fx-forward-points/run-fx-forward-points.ts","--supervisor") -WorkingDirectory $workspace -RedirectStandardOutput(Join-Path $runtime "supervisor.log") -RedirectStandardError(Join-Path $runtime "supervisor.error.log") -WindowStyle Hidden -PassThru;$p.Id|Set-Content(Join-Path $runtime "supervisor.pid") -Encoding ascii;[pscustomobject]@{PID=$p.Id;Alive=-not $p.HasExited;Runtime=$runtime}
